// Compute the magnitude of the separation vector
double r_mag = std::sqrt(r.x * r.x + r.y * r.y + r.z * r.z);

// Handle edge case: zero separation (avoid division by zero)
if (r_mag == 0.0) {
    return vec3{0.0, 0.0, 0.0};
}

// Compute the common term (sigma / r)
double sigma_r = sigma / r_mag;
double sigma_r_6 = sigma_r * sigma_r * sigma_r * sigma_r * sigma_r * sigma_r;
double sigma_r_12 = sigma_r_6 * sigma_r_6;

// Compute the scalar multiplier for the force
double multiplier = 24.0 * epsilon * (2.0 * sigma_r_12 - sigma_r_6) / r_mag;

// Return the force vector
return vec3{
    multiplier * r.x,
    multiplier * r.y,
    multiplier * r.z
};

